import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement } from 'chart.js';
import { Bar, Doughnut } from 'react-chartjs-2';
import api from '../api';
import '../App.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement);

function Archive() {
  const [history, setHistory] = useState([]);
  const [chartData, setChartData] = useState({ roles: {}, skills: {}, cgpa: {} });
  const navigate = useNavigate();

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      const res = await api.get('/api/predict/history');
      const data = res.data.history || [];
      setHistory(data);
      processChartData(data);
    } catch (err) {
      console.error(err);
    }
  };

  const processChartData = (data) => {
    const rolesCount = {};
    const skillsCount = {};
    const cgpaByMajor = {};

    data.forEach(item => {
      try {
        const preds = JSON.parse(item.predictedOutput);
        if (preds && preds.length > 0) {
          const topRole = preds[0].role;
          rolesCount[topRole] = (rolesCount[topRole] || 0) + 1;
        }
      } catch (e) {}

      if (item.skills) {
        item.skills.split(',').forEach(skill => {
          const s = skill.trim();
          if (s) skillsCount[s] = (skillsCount[s] || 0) + 1;
        });
      }

      const major = item.major;
      const cgpa = parseFloat(item.cgpa);
      if (major && !isNaN(cgpa)) {
        if (!cgpaByMajor[major]) cgpaByMajor[major] = { sum: 0, count: 0 };
        cgpaByMajor[major].sum += cgpa;
        cgpaByMajor[major].count += 1;
      }
    });

    const sortedSkills = Object.entries(skillsCount).sort((a, b) => b[1] - a[1]).slice(0, 10);
    const skillsObj = {};
    sortedSkills.forEach(([k, v]) => skillsObj[k] = v);

    const avgCgpa = {};
    Object.keys(cgpaByMajor).forEach(major => {
      avgCgpa[major] = cgpaByMajor[major].sum / cgpaByMajor[major].count;
    });

    setChartData({ roles: rolesCount, skills: skillsObj, cgpa: avgCgpa });
  };

  const roleChartConfig = {
    labels: Object.keys(chartData.roles),
    datasets: [{
      label: '# of Times as Top Prediction',
      data: Object.values(chartData.roles),
      backgroundColor: 'rgba(0, 242, 254, 0.5)'
    }]
  };

  const skillsChartConfig = {
    labels: Object.keys(chartData.skills),
    datasets: [{
      label: 'Skill Frequency',
      data: Object.values(chartData.skills),
      backgroundColor: ['#00f2fe', '#4facfe', '#28a745', '#ffc107', '#dc3545', '#6f42c1']
    }]
  };

  const cgpaChartConfig = {
    labels: Object.keys(chartData.cgpa),
    datasets: [{
      label: 'Average CGPA',
      data: Object.values(chartData.cgpa),
      backgroundColor: 'rgba(79, 172, 254, 0.5)'
    }]
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    color: '#e4e4e7',
    scales: {
      y: { ticks: { color: '#e4e4e7' } },
      x: { ticks: { color: '#e4e4e7' } }
    },
    plugins: {
      legend: { labels: { color: '#e4e4e7' } }
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('jwt_token');
    navigate('/login');
  };

  return (
    <div>
      <div className="stars"></div>
      <div className="sidebar">
        <h1>Welcome Back!</h1>
        <button onClick={() => navigate('/home')}>
          <i className="fa-solid fa-house"></i> Home
        </button>
        <button className="active">
          <i className="fa-solid fa-box-archive"></i> View Archive
        </button>
        <button onClick={handleLogout} style={{ marginTop: 'auto', marginBottom: '30px' }}>
          <i className="fa-solid fa-right-from-bracket"></i> Logout
        </button>
      </div>

      <main className="main-content" style={{ display: 'flex', flexDirection: 'column', padding: '20px', height: '100vh', overflow: 'hidden' }}>

        <div style={{ height: '50%', overflowY: 'auto', overflowX: 'auto', marginBottom: '20px', border: '1px solid #2f2f44', borderRadius: '8px', background: '#1c1c28' }}>
          <h2 style={{ textAlign: 'center', margin: '20px 0', color: '#fff' }}>Your Prediction History</h2>
          <table id="predictionResultTable">
            <thead style={{ position: 'sticky', top: 0, background: '#2a2a40', zIndex: 1 }}>
              <tr>
                <th>Major</th>
                <th>CGPA</th>
                <th>Degree</th>
                <th>Skills</th>
                <th>Top Prediction</th>
              </tr>
            </thead>
            <tbody>
              {history.length === 0 ? (
                <tr><td colSpan="5" style={{ textAlign: 'center', color: '#fff' }}>No history yet. Go make some predictions!</td></tr>
              ) : (
                history.map((pred, idx) => {
                  let topRole = "N/A";
                  let topScore = "N/A";
                  try {
                    const preds = JSON.parse(pred.predictedOutput);
                    if (preds && preds.length > 0) {
                      topRole = preds[0].role;
                      topScore = preds[0].score;
                    }
                  } catch (e) {}

                  return (
                    <tr key={idx}>
                      <td style={{ color: '#fff' }}>{pred.major}</td>
                      <td style={{ color: '#a1a1aa' }}>{pred.cgpa}</td>
                      <td style={{ color: '#a1a1aa' }}>{pred.degree}</td>
                      <td style={{ color: '#a1a1aa' }}>{pred.skills}</td>
                      <td style={{ color: '#a1a1aa' }}>{topRole} ({topScore})</td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        </div>

        <div style={{ height: '50%', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', gap: '20px' }}>
          <div style={{ background: '#1c1c28', border: '1px solid #2f2f44', borderRadius: '12px', padding: '20px' }}>
             <h3 style={{ textAlign: 'center', color: '#fff', marginTop: 0 }}>Top Predicted Roles</h3>
             <div style={{ height: '90%' }}>
                <Bar data={roleChartConfig} options={chartOptions} />
             </div>
          </div>
          <div style={{ background: '#1c1c28', border: '1px solid #2f2f44', borderRadius: '12px', padding: '20px' }}>
             <h3 style={{ textAlign: 'center', color: '#fff', marginTop: 0 }}>Most Common Skills</h3>
             <div style={{ height: '90%' }}>
                <Doughnut data={skillsChartConfig} options={{ ...chartOptions, scales: {} }} />
             </div>
          </div>
          <div style={{ background: '#1c1c28', border: '1px solid #2f2f44', borderRadius: '12px', padding: '20px' }}>
             <h3 style={{ textAlign: 'center', color: '#fff', marginTop: 0 }}>Average CGPA by Major</h3>
             <div style={{ height: '90%' }}>
                <Bar data={cgpaChartConfig} options={{ ...chartOptions, indexAxis: 'y' }} />
             </div>
          </div>
        </div>

      </main>
    </div>
  );
}

export default Archive;
